// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract Box {
    /// @custom:storage-location erc7201:box.main
    struct MainStorage {
        uint256 value;
        address owner;
    }

    function _main() private pure returns (MainStorage storage $) {
        assembly {
            $.slot := 0x9b779b17422d0df92223018b32b4d1fa46e071723d6817e2486d003becc55f00
        }
    }

    function value() external view returns (uint256) {
        return _main().value;
    }
}

