reinitializer-note.source:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract ReinitBase {
    modifier reinitializer(uint8 version) {
        _;
    }

    function bump(uint8 version) public reinitializer(version) {}
}

contract ReinitDerived is ReinitBase {
    uint256 stored;

    function get() external view returns (uint256) {
        return stored;
    }
}

